const cfg = $input.first()?.json || {};
const errors = [];

function cleanUrl(value) {
  return String(value || '').trim().replace(/\/+$/, '');
}

const supabaseUrl = cleanUrl(cfg.supabaseUrl);
const opsApiUrl = String(cfg.opsApiUrl || '').trim();
const supabaseFetchLimit = Number(cfg.supabaseFetchLimit || 100);
const stepCm = Number(cfg.stepCm || 20);
const maxLongSideCm = Number(cfg.maxLongSideCm || 300);

if (!/^https:\/\//i.test(supabaseUrl)) errors.push('SUPABASE_URL must be an https URL');
if (!/^https:\/\//i.test(opsApiUrl)) errors.push('NEONTRIP_OPS_BASE_URL/opsApiUrl must resolve to an https URL');
if (cfg.agentTokenConfigured !== true) errors.push('SUPPLIER_PRICE_REVIEW_AGENT_API_TOKEN is missing');
if (!Number.isFinite(supabaseFetchLimit) || supabaseFetchLimit < 1 || supabaseFetchLimit > 250) errors.push('supabaseFetchLimit must be 1..250');
if (!Number.isFinite(stepCm) || stepCm < 5 || stepCm > 100) errors.push('stepCm must be 5..100');
if (!Number.isFinite(maxLongSideCm) || maxLongSideCm < 1 || maxLongSideCm > 300) errors.push('maxLongSideCm must stay at or below 300 for internal review suggestions');

if (errors.length) {
  throw new Error('Supplier price review queue config failed: ' + errors.join('; '));
}

return [{
  json: {
    ...cfg,
    supabaseUrl,
    supabaseRestUrl: supabaseUrl + '/rest/v1',
    opsApiUrl,
    supabaseFetchLimit,
    stepCm,
    maxLongSideCm
  }
}];

const cfg = $('Config Preflight').first().json;
const rows = $input.all()
  .flatMap((item) => Array.isArray(item.json) ? item.json : [item.json])
  .filter(Boolean);

function finiteNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

const eligible = rows.filter((row) => {
  return row.id &&
    row.product_model_family === 'neonflex_candidate' &&
    row.excluded_from_neonflex_training === false &&
    row.validation_status === 'usable' &&
    row.review_status === 'approved' &&
    finiteNumber(row.width_cm) !== null &&
    finiteNumber(row.height_cm) !== null &&
    finiteNumber(row.production_price) !== null &&
    finiteNumber(row.shipping_price) !== null;
});

if (!eligible.length) {
  return [{ json: { noItems: true, message: 'No approved Neonflex training items ready for price review queue' } }];
}

return eligible.slice(0, cfg.supabaseFetchLimit).map((row) => ({
  json: {
    action: 'create_from_training_item',
    operatorName: 'n8n Supplier Price Review Queue',
    trainingItemId: row.id,
    sourceSizeLabel: row.size_label || null,
    trainingItem: {
      trainingItemId: row.id,
      stepCm: cfg.stepCm,
      maxLongSideCm: cfg.maxLongSideCm,
      sourceLabel: row.size_label || null,
      currency: row.currency || 'USD',
      featureValues: {
        n8n_workflow: 'supplier_price_prediction_review_queue_v0_1',
        source_training_reviewed_at: row.reviewed_at || null,
        source_training_created_at: row.created_at || null
      }
    }
  }
}));

const responses = $input.all().map((item) => item.json || {});
let predictionRows = 0;
for (const response of responses) {
  if (Array.isArray(response.items)) predictionRows += response.items.length;
}

let trainingItemIds = [];
try {
  trainingItemIds = $('Build Review Queue Requests').all()
    .map((item) => item.json?.trainingItemId)
    .filter(Boolean);
} catch (error) {
  trainingItemIds = [];
}

return [{
  json: {
    ok: true,
    action: 'supplier_price_review_queue_run',
    trainingItemsPosted: responses.length,
    predictionRowsReturned: predictionRows,
    trainingItemIds,
    checkedAt: new Date().toISOString()
  }
}];
